        let next_imbalance_penalty = (next_cpu_norm - next_ram_norm).abs();
        if next_imbalance_penalty < imbalance_penalty {
            0.5
        } else {
            1.0
        }
    };

    let score = cpu_norm + ram_norm + imbalance_penalty + step_ratio * residual_ratio * lookahead_score;
    score
}

